@startuml

class Department {}

class Room {}

class Bed {
  + Category : StayCategory
}

class StayCategory {
  + Price : double
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class Stay {
  + StartDate : date
  + Status : string
}

class Registration {
  + RegistrationDate : date
  + IdentificationData : string
}

class Assessment {
  + Needs : string
  + ResultingStayType : StayType
}

class WaitingListPosition {
  + Position : int
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + Amount : double
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class Payment {
  + Amount : double
  + Date : date
}

Department "1" -- "*" Room
Room "1" -- "*" Bed
Bed "1" -- "1" StayCategory
Inhabitant "1" -- "*" Registration
Inhabitant "1" -- "*" Stay
Stay "1" -- "1" StayCategory
Inhabitant "1" -- "*" Stay
Stay "1" -- "*" Invoice
Inhabitant "1" -- "*" Payment
Invoice "1" -- "*" Payment
Invoice "1" -- "0..1" CreditNote
Inhabitant "1" -- "0..*" WaitingListPosition
StayCategory "1" -- "*" WaitingListPosition
Inhabitant "1" -- "0..*" Proposal
StayCategory "1" -- "*" Proposal

@enduml

